-- demo seed (spec.md §37 Phase 6)
-- 1) mock provider 用の place / evidence 一式 (外部 API 障害時の保険 §5.4)
-- 2) 矛盾 (§15) を含む Evidence ペア 1 組 (⚠表示をデモで確実に見せる)
-- 3) 類似調査デモ用の過去 Investigation (embedding 計算済み)
--
-- 固定 UUID を使い、db reset ごとに同じ状態を再現する。
-- 店舗データは mock 専用のデモ用データ (#297 で HotPepper 由来の実データを撤去)。
-- provider='mock' は「live 調査ガード」(pipeline.ts) の対象で、実 API クレジットを消費しない。

-- 共有 TEST ユーザーはローカル開発専用で、seed.sql だけが作成する (#438)。
-- migration から auth.users を provision しない（本番に作成済みだった行は
-- 202608160900_disable_shared_test_user.sql が無効化済み）。upsert 側でも
-- banned_until = null とパスワード再設定を行い、無効化済みの行に対して
-- seed を流した場合でも有効なログイン状態へ復元する。

insert into auth.users (
  instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
  confirmation_token, recovery_token, email_change_token_new, email_change,
  email_change_token_current, reauthentication_token, raw_app_meta_data,
  raw_user_meta_data, created_at, updated_at, is_anonymous
) values (
  '00000000-0000-0000-0000-000000000000',
  '00000000-0000-4000-8000-00000000e571',
  'authenticated', 'authenticated', 'test@example.com',
  extensions.crypt('TEST', extensions.gen_salt('bf')), now(), '', '', '', '', '', '',
  '{"provider":"email","providers":["email"]}'::jsonb,
  '{"display_name":"TEST","name":"TEST"}'::jsonb, now(), now(), false
)
on conflict (id) do update set
  email = excluded.email,
  encrypted_password = excluded.encrypted_password,
  email_confirmed_at = excluded.email_confirmed_at,
  confirmation_token = excluded.confirmation_token,
  recovery_token = excluded.recovery_token,
  email_change_token_new = excluded.email_change_token_new,
  email_change = excluded.email_change,
  email_change_token_current = excluded.email_change_token_current,
  reauthentication_token = excluded.reauthentication_token,
  raw_app_meta_data = excluded.raw_app_meta_data,
  raw_user_meta_data = excluded.raw_user_meta_data,
  updated_at = excluded.updated_at,
  banned_until = null,
  is_anonymous = false;

-- 過去調査デモの参照整合性だけを満たす、ローカル seed 専用の所有者。
-- identity / session を作らず、banned 状態に固定してログイン経路を持たせない。
insert into auth.users (
  instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
  confirmation_token, recovery_token, email_change_token_new, email_change,
  email_change_token_current, reauthentication_token, raw_app_meta_data,
  raw_user_meta_data, created_at, updated_at, banned_until, is_anonymous
) values (
  '00000000-0000-0000-0000-000000000000',
  '00000000-0000-4000-8000-00000000d3a0',
  'authenticated', 'authenticated', null, '', null, '', '', '', '', '', '',
  '{"provider":"anonymous","providers":[]}'::jsonb,
  '{"seed_demo_owner":true}'::jsonb,
  now(), now(), 'infinity'::timestamptz, true
)
on conflict (id) do update set
  banned_until = 'infinity'::timestamptz,
  is_anonymous = true,
  raw_app_meta_data = excluded.raw_app_meta_data,
  raw_user_meta_data = excluded.raw_user_meta_data,
  updated_at = excluded.updated_at;

insert into auth.identities (
  provider_id, user_id, identity_data, provider, last_sign_in_at, created_at, updated_at, id
) values (
  'test@example.com', '00000000-0000-4000-8000-00000000e571',
  '{"sub":"00000000-0000-4000-8000-00000000e571","email":"test@example.com","email_verified":true}'::jsonb,
  'email', now(), now(), now(), '00000000-0000-4000-8000-00000000e572'
)
on conflict (provider_id, provider) do update set
  identity_data = excluded.identity_data,
  updated_at = excluded.updated_at;

insert into public.profiles (id, display_name)
values ('00000000-0000-4000-8000-00000000e571', 'TEST')
on conflict (id) do update set display_name = excluded.display_name;

